  'byok.title': 'ಅತ್ಯಾಧುನಿಕ ಕೀ',
  'byok.heroTitle': 'ಅತ್ಯಾಧುನಿಕ ಕೀ (BYOK)',
  'byok.heroBody': 'ನಿಮ್ಮ ಸಾಧನದಲ್ಲಿ ಮಾತ್ರ ಇರುವ ಮಾಸ್ಟರ್ ಕೀ ಅನ್ನು ನಿರ್ವಹಿಸಿ. ಎಲ್ಲಾ ಎನ್‌ಕ್ರಿಪ್ಟ್ ಮಾಡಿದ ಚಾಟ್‌ಗಳು ಈ ಕೀ ಬಳಸುತ್ತವೆ. ಸರ್ವರ್ ಪರಿಶೀಲನೆಗಾಗಿ ಕೇವಲ ಬೆನ್ನುಹತ್ತಿ ಉಳಿಸುತ್ತದೆ - ಕೀ ಸ್ವತಃ ಎಂದಿಗೂ ಅಲ್ಲ.',
