  'byok.phraseTitle': 'ಈ ವಾಕ್ಯವನ್ನು ಬರೆಯಿರಿ',
  'byok.phraseBody': 'ಈ ವಾಕ್ಯವು ನಿಮ್ಮ ಕೀ ಅನ್ನು ಇತರ ಸಾಧನದಲ್ಲಿ ಪುನಃ ಪಡೆಯಲು ಏಕೈಕ ಮಾರ್ಗವಾಗಿದೆ. ಸುರಕ್ಷಿತ ಮತ್ತು ಆಫ್-ಲೈನ್ ಸ್ಥಳದಲ್ಲಿ ಬರೆಯಿರಿ. ತಂಡದ ಯಾರಿಗೂ ನೀವು ಅದನ್ನು ಪುನಃ ಪಡೆಯಲು ಸಹಾಯ ಮಾಡಲು ಸಾಧ್ಯವಿಲ್ಲ.',
