  'privacy.discoverableDesc': 'ನಿಷ್ಕ್ರಿಯವಾದಾಗ, ಯಾರೂ ನಿಮ್ಮನ್ನು ದೂರವಾಣಿ ಮೂಲಕ ಸಂಪರ್ಕಿಸುವಾಗ ಕಂಡುಹಿಡಿಯುವುದಿಲ್ಲ. ನೀವು ಯಾರಾದರೂ ಜೊತೆ ಚಾಟ್ ಪ್ರಾರಂಭಿಸಲು ಇನ್ನೂ ಸಾಧ್ಯವಾಗಿದೆ.',
  'privacy.screenBlock': 'ಸ್ಕ್ರೀನ್ ಶಾಟ್‌ಗಳನ್ನು ತಡೆಯಿರಿ',
  'privacy.screenBlockLabel': 'ಆಪ್‌ನಲ್ಲಿ ಸ್ಕ್ರೀನ್ ಶಾಟ್‌ಗಳನ್ನು ತಡೆಯಿರಿ',
  'privacy.screenBlockDesc': 'ಆಂಡ್ರಾಯ್ಡ್‌ನಲ್ಲಿ, "ಇತ್ತೀಚಿನ" ನಲ್ಲಿ ಛಾಯಾಚಿತ್ರಗಳು ಕಪ್ಪಾಗುತ್ತವೆ. ಐಒಎಸ್‌ನಲ್ಲಿ, ಸ್ಕ್ರೀನ್ ಶಾಟ್‌ಗಳನ್ನು ನಿಲ್ಲಿಸಲಾಗುತ್ತದೆ. ಮೊಬೈಲ್ ಫೋನ್‌ನ ಫೋಟೋವನ್ನು ತಡೆಯುವುದಿಲ್ಲ.',
  'privacy.proxyTor': 'ಪ್ರಾಕ್ಸಿ / ಟೋರ್',
  'privacy.proxyEnable': 'ಪ್ರಾಕ್ಸಿ ಮೂಲಕ ಸಂಪರ್ಕ',
  'privacy.proxyDesc': 'ಎಲ್ಲಾ SOCKS5 ಮೂಲಕ ಮಾರ್ಗದರ್ಶನ ಮಾಡುತ್ತದೆ. ಅತ್ಯಾಧುನಿಕ - ನೀವು ಏನು ಮಾಡುತ್ತಿದ್ದೀರಿ ಎಂಬುದನ್ನು ತಿಳಿದಿದ್ದರೆ ಮಾತ್ರ ಸಕ್ರಿಯಗೊಳಿಸಿ.',
  'privacy.proxyHost': 'ಹೋಸ್ಟ್',
