  'privacy.proxyUser': 'ಬಳಕೆದಾರ (ಐಚ್ಛಿಕ)',
  'privacy.proxyPass': 'ಪಾಸ್ವರ್ಡ್ (ಐಚ್ಛಿಕ)',
  'privacy.useTor': 'ಟೋರ್ ಬಳಸಿರಿ',
  'privacy.useTorDesc': 'ಎಲ್ಲಾ ಸ್ಥಳೀಯ ಟೋರ್ ಇನ್ಸ್ಟಾನ್ಸ್ ಮೂಲಕ ಮಾರ್ಗದರ್ಶನ ಮಾಡುತ್ತದೆ. ಇದು ಆಪ್ ಅನ್ನು ನಿಧಾನಗತಿಯಲ್ಲಿ ಮಾಡಬಹುದು. ಕೈಗಾರಿಕ ಪ್ರಾಕ್ಸಿಯ ಮೇಲೆ ಆದ್ಯತೆ ಹೊಂದಿದೆ.',
  'privacy.vpnSuggestTitle': 'VPN ಬಳಸಲು ಪರಿಗಣಿಸಿ',
