  "waImport.destDirectSubDate": "ಮುಂದುವರಿಕೆ: WhatsApp ಇತಿಹಾಸವು ದಿನಾಂಕ ಮತ್ತು ಸಮಯದ ಪ್ರಕಾರ ನೀವು ಈಗಾಗಲೇ Chatyy ನಲ್ಲಿ ಹಂಚಿಕೊಂಡ ಸಂದೇಶಗಳ ನಡುವೆ ಸೇರುತ್ತದೆ. {name} ಅವರೂ ಇದನ್ನು ನೋಡುತ್ತಾರೆ, ಆಮದು ಮಾಡಿದ್ದು ಎಂದು ಗುರುತಿಸಲಾಗಿದೆ.",
