  "waImport.matchContactPhone": "ನಿಮ್ಮ ಸಂಪರ್ಕಗಳಲ್ಲಿರುವ ಅದೇ ಸಂಖ್ಯೆ",
  "waImport.agendaAskTitle": "ಸಂಪರ್ಕಗಳ ಸಂಖ್ಯೆಯಿಂದ ಹುಡುಕಿ",
  "waImport.agendaAskBody": "WhatsApp ಕಳುಹಿಸಿದವರನ್ನು ನಿಮ್ಮ ಸಂಪರ್ಕಗಳಲ್ಲಿನ ಹೆಸರಿನಲ್ಲಿ ಉಳಿಸಿದೆ. ಸಂಖ್ಯೆಯಿಂದ ಸರಿಯಾದ ಖಾತೆ ಹುಡುಕಲು Chatyy ಈ ಹೆಸರನ್ನು ನಿಮ್ಮ ಸಂಪರ್ಕಗಳಲ್ಲಿ ಹುಡುಕಿ chatyy.com.br ಗೆ ಸಂಖ್ಯೆಗಳ ಒಂದು ಕೋಡ್ (SHA-256 ಹ್ಯಾಶ್) ಮಾತ್ರ ಕಳುಹಿಸುತ್ತದೆ — ಎಂದಿಗೂ ಸಂಖ್ಯೆಯನ್ನೇ ಅಲ್ಲ, ಏನನ್ನೂ ಉಳಿಸಲಾಗುವುದಿಲ್ಲ. ಇದಿಲ್ಲದೆ ಹುಡುಕಾಟ ಹೆಸರಿನಿಂದ ಮಾತ್ರ.",
  "waImport.agendaAllow": "ಅನುಮತಿಸಿ",
  "waImport.agendaNotNow": "ಈಗ ಬೇಡ",
  "waImport.agendaOpenSettings": "ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ತೆರೆಯಿರಿ",
  "waImport.agendaDeniedHint": "ಸಂಪರ್ಕಗಳಿಗೆ ಪ್ರವೇಶವಿಲ್ಲ: ವ್ಯಕ್ತಿಯನ್ನು ಹೆಸರಿನಿಂದ ಮಾತ್ರ ಸೂಚಿಸಲಾಗುತ್ತದೆ. ಸಂಖ್ಯೆಯಿಂದ ದೃಢೀಕರಿಸಲು ಸಂಪರ್ಕಗಳ ಪ್ರವೇಶವನ್ನು ಅನುಮತಿಸಿ.",
