  "walletHow.buyBody": "ಲೈವ್, ರೀಲ್ಸ್, ಪೋಸ್ಟ್ ಮತ್ತು ಚಾಟ್‌ಗಳಲ್ಲಿ ಉಡುಗೊರೆ ಕಳುಹಿಸಲು. ಇವನ್ನು ಹಿಂಪಡೆಯಲು ಅಥವಾ ಹಣಕ್ಕೆ ಬದಲಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ — ಇದು App Store ಮತ್ತು Google Play ನಿಯಮ.",
