  "walletHow.earnBodyValue": "ಯಾರಾದರೂ ನಿಮಗೆ ಉಡುಗೊರೆ ಕಳುಹಿಸಿದರೆ, ಅದು ನಿಮ್ಮ ಖಾತೆಯಲ್ಲಿ ರಿಯಾಲ್‌ನಲ್ಲಿ ಗಳಿಕೆಯಾಗುತ್ತದೆ. ಪಡೆದ ಪ್ರತಿಯೊಂದು ವಜ್ರದ ಮೌಲ್ಯ {value}.",
  "walletHow.holdBody": "ಪಡೆದ ಪ್ರತಿಯೊಂದು ಉಡುಗೊರೆ ಕೆಲವು ದಿನ ತಡೆಹಿಡಿಯಲಾಗುತ್ತದೆ (ಸ್ಟೋರ್ ಮರುಪಾವತಿ ಅವಧಿ). ನಂತರ ಹಿಂಪಡೆಯಬಹುದಾದ ಬ್ಯಾಲೆನ್ಸ್‌ಗೆ ಸೇರುತ್ತದೆ.",
